// Simulated counterfactual prototype outputs — not generated by real DiCE, FACE, Wachter models or a trained clinical AI model.

export const counterfactualMethods = [
  {
    id: 'wachter',
    name: 'Wachter',
    type: 'Baseline Counterfactual',
    description:
      'Finds a nearby valid change using as few feature modifications as possible.',
  },
  {
    id: 'dice',
    name: 'DiCE',
    type: 'Diverse Counterfactual Explanations',
    description:
      'Generates multiple alternative intervention pathways while respecting selected feature constraints.',
  },
  {
    id: 'face',
    name: 'FACE',
    type: 'Feasibility-Oriented Counterfactual',
    description:
      'Prioritizes more plausible and realistic feature combinations.',
  },
];

export const defaultCounterfactualCandidateLimit = 5;

const templates = [
  { method: 'wachter', index: 1, factorIndexes: [0], validity: 0.90, proximity: 0.88, diversity: 0.40, feasibilityPreview: 'Medium', riskReduction: 0.19 },
  { method: 'dice', index: 1, factorIndexes: [0, 1], validity: 0.95, proximity: 0.82, diversity: 0.90, feasibilityPreview: 'High', riskReduction: 0.29, affordabilityAdapted: true },
  { method: 'face', index: 1, factorIndexes: [0, 2], validity: 0.93, proximity: 0.86, diversity: 0.78, feasibilityPreview: 'High', riskReduction: 0.25, affordabilityAdapted: true },
  { method: 'wachter', index: 2, factorIndexes: [1], validity: 0.92, proximity: 0.91, diversity: 0.55, feasibilityPreview: 'High', riskReduction: 0.15 },
  {
    method: 'dice', index: 2, protectedAttempt: true, validity: 0.98, proximity: 0.55,
    diversity: 0.98, feasibilityPreview: 'Rejected', riskReduction: 0.42,
  },
];

function targetForFactor(factor, variant) {
  const targets = {
    'Dietary Diversity': ['Medium', 'Improved'],
    'Food Group Variety': ['Improved', 'High'],
    'Meal Frequency': ['Age-appropriate', 'Regular'],
    'Clinic Follow-up': ['Regular', 'Scheduled'],
    'Sanitation Practice': ['Improved', 'Consistent'],
    'Safe Water Practice': ['Consistent', 'Improved'],
    'Handwashing Practice': ['Consistent', 'Improved'],
    'Nutrition Awareness': ['Improved', 'Counselling completed'],
    'Nutrition Counselling': ['Scheduled', 'Completed'],
    'Complementary Feeding Practice': ['Age-appropriate', 'Improved'],
    'Responsive Feeding Practice': ['Consistently followed', 'Improved'],
  };
  const values = targets[factor.name] || ['Improved', 'Supported'];
  return values[variant % values.length];
}

function estimatedRiskLevel(probability) {
  if (probability >= 0.75) return 'High';
  if (probability >= 0.45) return 'Medium';
  return 'Low';
}

function titleForChanges(changes) {
  if (changes.length === 1) return `Improve ${changes[0].featureName.toLowerCase()}`;
  return `Improve ${changes.map((change) => change.featureName.toLowerCase()).join(' + ')}`;
}

export function calculatePrototypeQuality(candidate) {
  if (candidate.guardrailExample) return 0.10;
  const normalizedSparsity = 1 / Math.max(1, candidate.sparsity);
  const normalizedReduction = Math.min(1, candidate.riskReduction / 0.35);
  return (
    candidate.validity * 0.30 +
    candidate.proximity * 0.20 +
    normalizedSparsity * 0.15 +
    candidate.diversity * 0.15 +
    normalizedReduction * 0.20
  );
}

export function generateCounterfactualCandidates(child, selectedFactors = []) {
  if (!child || selectedFactors.length === 0) return [];

  const originalProbability = child.probability / 100;
  const childAdjustment = (((Number(child.childId.split('-')[1]) || 1) - 1) % 4) * 0.01;

  return templates.map((template, templateIndex) => {
    const factors = template.protectedAttempt
      ? []
      : template.factorIndexes
        .map((factorIndex) => selectedFactors[factorIndex % selectedFactors.length])
        .filter((factor, index, items) => factor && items.findIndex((item) => item.id === factor.id) === index);
    const changes = template.protectedAttempt
      ? [{
          featureId: `${child.childId.toLowerCase()}-rf-household-resource`,
          featureName: 'Household Resource Level',
          currentValue: child.feasibilityContext.householdResourceLevel,
          targetValue: 'High',
        }]
      : factors.map((factor, index) => ({
          featureId: factor.id,
          featureName: factor.name,
          currentValue: factor.currentValue,
          targetValue: targetForFactor(factor, templateIndex + index),
        }));
    const achievableReduction = Math.min(template.riskReduction - childAdjustment, originalProbability - 0.18);
    const riskReduction = Math.max(0.08, Number(achievableReduction.toFixed(2)));
    const estimatedProbability = Number(Math.max(0.15, originalProbability - riskReduction).toFixed(2));
    const candidate = {
      id: `${template.method}-${child.childId.toLowerCase()}-${String(template.index).padStart(3, '0')}`,
      method: template.method,
      title: titleForChanges(changes),
      changes,
      originalProbability,
      estimatedProbability,
      estimatedRiskLevel: estimatedRiskLevel(estimatedProbability),
      riskReduction,
      validity: template.validity,
      proximity: template.proximity,
      sparsity: changes.length,
      diversity: template.diversity,
      feasibilityPreview: template.feasibilityPreview,
      affordabilityAdapted: Boolean(template.affordabilityAdapted),
      guardrailExample: Boolean(template.protectedAttempt),
      notes: template.protectedAttempt
        ? 'Simulated unrealistic proposal retained only to demonstrate protected-feature rejection.'
        : 'Simulated deterministic prototype counterfactual.',
    };
    return { ...candidate, qualityScore: calculatePrototypeQuality(candidate) };
  });
}

export function rankCounterfactualCandidates(candidates = []) {
  return [...candidates]
    .sort((a, b) => b.qualityScore - a.qualityScore)
    .map((candidate, index) => ({ ...candidate, rank: index + 1 }));
}
